128	/**
129	 * A reusable "heading + list of links" column — generalised from the footer-only
130	 * `footerNavGroup` type (see scripts/contentful/content-types/navGroup.js) so the header
131	 * mega-menu can reference the same shape. `showContactChannels` is a footer-only flag;
132	 * a header mega-menu group simply never sets it.
133	 */
134	export type NavGroupEntry = {
135	  sys: {
136	    id: string;
137	    contentType: { sys: { id: 'navGroup' } };
138	  };
139	  fields: {
140	    /** Editor-facing label only — not localized, not rendered. */
141	    internalTitle: string;
142	    heading: string;
143	    readonly links: ReadonlyArray<LinkEntry>;
144	    /**
145	     * Renders the contact-channel icon row beneath this group's links.
146	     *
147	     * A flag rather than matching the heading text: `heading` is a localised Contentful
148	     * value, so `heading === 'Contact'` silently stops matching the moment an editor writes
149	     * "Kontakt" or "Contacto" — and this footer ships to eight storefronts.
150	     */
151	    showContactChannels?: boolean;
152	  };
