155	export type FooterConfigEntry = {
156	  sys: {
157	    id: string;
158	    contentType: { sys: { id: 'footerConfig' } };
159	  };
160	  fields: {
161	    internalTitle: string;
162	    subscribeHeading?: string;
163	    subscribeBody?: string;
164	    // Read-only both ways. The footer only ever .maps these, but footer/index.stories.content.ts's
165	    // FOOTER_FIXTURE is a plain module singleton multiple stories in index.stories.tsx read
166	    // directly, so an in-place push/sort/index-assign anywhere would corrupt every other
167	    // story reading the same object. ReadonlyArray blocks push/pop/splice/sort/reverse/
