169	    // whole array out. Matches BottomBarProps.legalLinks in footer/index.tsx, which already
170	    // types its array as ReadonlyArray<>.
171	    readonly navGroups: ReadonlyArray<NavGroupEntry>;
172	    readonly legalLinks?: ReadonlyArray<LinkEntry>;
