288	export type SizeGuideTableRow = {
289	  label: string;
290	  convertible: boolean;
291	  values: (string | number)[];
292	  spans?: number[];
293	  /** When true, this row renders as a bold sub-header (for labelless grouped tables). */
294	  isHeader?: boolean;
295	};
296	
297	export type SizeGuideTable = {
298	  columns: string[];
299	  columnSpan?: number;
300	  /**
301	   * Sub-column labels rendered in a second thead row beneath the main column headers.
302	   * Each label repeats once per main column group. The first column (SIZE/label) spans
303	   * both header rows via rowSpan=2. Used for the gloves table (S/M | M/L repeating
304	   * under SHORT GLOVES and LONG GLOVES).
305	   */
306	  subColumns?: string[];
307	  rows: SizeGuideTableRow[];
308	  /**
309	   * When true, omits the label column and thead entirely. Rows alternate between
310	   * isHeader=true (bold group header) and isHeader=false (measurement values).
311	   * Used for the hat table's 3-level grouped layout.
312	   */
313	  labelless?: boolean;
314	  /**
315	   * Optional custom section heading rendered above this table. When present,
316	   * overrides the default FormattedMessage label (e.g. "SIZE CONVERSIONS").
317	   * Allows reusing bodyMeasurementsTable/garmentMeasurementsTable for guides
318	   * that need multiple size conversion sections with different titles (e.g. jewellery).
319	   */
320	  heading?: string;
321	  /** When true, suppresses the section heading entirely (e.g. the hat table). */
322	  hideHeading?: boolean;
323	};
324	
325	export type SizeGuideEntry = {
326	  sys: { id: string; contentType: { sys: { id: 'sizeGuide' } } };
327	  fields: {
328	    internalTitle: string;
329	    key: string;
330	    label: string;
331	    /** Typed but not rendered — @contentful/rich-text-react-renderer not installed (Hard Rule #7). */
332	    measurementInstructions?: ContentfulRichText;
333	    sizeConversionsDescription?: string;
334	    sizeConversionsTable?: SizeGuideTable;
335	    bodyMeasurementsDescription?: string;
336	    bodyMeasurementsTable?: SizeGuideTable;
337	    garmentMeasurementsDescription?: string;
338	    garmentMeasurementsTable?: SizeGuideTable;
339	    hasCmInchToggle: boolean;
340	    /**
341	     * Initial unit for the CM/INCH toggle. Defaults to 'cm' when absent.
342	     * Set to 'inch' for guides where inch is the primary display unit (e.g. hats, gloves).
343	     */
344	    defaultUnit?: 'cm' | 'inch';
345	    localeNote?: string;
346	    locales?: string[];
347	    /** Rendered only when all three table fields are absent. */
348	    image?: ContentfulAsset;
349	  };
350	};
