cd /private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/3efd3b37-36b0-40bc-9b5a-619ce14b7fdb/scratchpad && node -e '
const pattern = /^size-guide__[a-z0-9_]+(__[a-z]{2}_[A-Z]{2})?$/;

// Real locales from regional.md, canonicalised exactly as useSizeGuide.ts does: locale.replace("-", "_")
// (String.prototype.replace with a plain string arg replaces the FIRST occurrence only)
const locales = [
  ["AU (root, + Oceania)", "en"],
  ["UK", "en-GB"],
  ["US domestic", "en-US"],
  ["US international", "en-US"],
  ["EU domestic (EN)", "en-GB"],
  ["EU domestic (FR)", "fr"],
  ["EU domestic (IT)", "it"],
  ["EU domestic (ES)", "es"],
  ["EU international", "en-CH"],
  ["HK", "en-HK"],
  ["ME", "en-AE"],
];

const slug = "clothing_op";
console.log("=== Testing the ACTUAL key useSizeGuide.ts would construct for each locale ===");
for (const [name, bmLocale] of locales) {
  const canonical = bmLocale.replace("-", "_");
  const key = `size-guide__${slug}__${canonical}`;
  const matches = pattern.test(key);
  console.log(`${name.padEnd(24)} BM=${bmLocale.padEnd(8)} canonical=${canonical.padEnd(6)} key="${key}"  regex_match=${matches}`);
}

console.log();
console.log("=== Dissecting WHY the lowercase-only ones (en/fr/it/es) still match ===");
console.log("Does the mandatory [a-z0-9_]+ alone (no optional group engaged) swallow the whole tail?");
const testKey = "size-guide__clothing_op__en";
console.log(testKey, "->", pattern.test(testKey));
// Confirm by checking a regex with the optional group REMOVED entirely still matches these
const withoutOptionalGroup = /^size-guide__[a-z0-9_]+$/;
console.log("Without optional locale group at all:", withoutOptionalGroup.test(testKey));
'

